import { useId } from 'react';

const DROP = 'M30 10.5C25.6 17.2 15 28 15 38a15 15 0 0 0 30 0C45 28 34.4 17.2 30 10.5z';

/**
 * AASTAR mark: palm-green tile, gold oil drop with a rising price line ending in a live-price dot, four-point
 * star. Same artwork as docs/brand/aastar-app-icon.svg (generated by docs/brand/make_icons.py) — keep in sync.
 */
export function LogoMark({ size = 36 }: { size?: number }) {
  const id = useId().replace(/:/g, '');
  return (
    <svg width={size} height={size} viewBox="0 0 64 64" role="img" aria-label="AASTAR">
      <defs>
        <linearGradient id={`bg${id}`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#18977E" />
          <stop offset=".55" stopColor="#0C5F53" />
          <stop offset="1" stopColor="#06322C" />
        </linearGradient>
        <linearGradient id={`dr${id}`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#FFDB7D" />
          <stop offset=".55" stopColor="#F1AD2C" />
          <stop offset="1" stopColor="#C97C06" />
        </linearGradient>
        <radialGradient id={`lt${id}`} cx="14" cy="8" r="44" gradientUnits="userSpaceOnUse">
          <stop offset="0" stopColor="#fff" stopOpacity=".18" />
          <stop offset="1" stopColor="#fff" stopOpacity="0" />
        </radialGradient>
      </defs>
      <rect width="64" height="64" rx="14.4" fill={`url(#bg${id})`} />
      <rect width="64" height="64" rx="14.4" fill={`url(#lt${id})`} />
      <rect x=".6" y=".6" width="62.8" height="62.8" rx="13.8" fill="none" stroke="#fff" strokeOpacity=".1"
            strokeWidth="1.2" />
      <path d={DROP} transform="translate(.8 1.4)" fill="#021F1B" fillOpacity=".3" />
      <path d={DROP} fill={`url(#dr${id})`} />
      <path d="M21.2 36.5c0-5 2.6-10.2 5.8-14.9" fill="none" stroke="#fff" strokeOpacity=".55" strokeWidth="2.2"
            strokeLinecap="round" />
      <path d="M21.2 44.2l5.2-5.2 4.4 3.2 6.8-9.6" fill="none" stroke="#073A33" strokeWidth="3.4"
            strokeLinecap="round" strokeLinejoin="round" />
      <circle cx="37.6" cy="32.6" r="2.9" fill="#fff" stroke="#073A33" strokeWidth="1.8" />
      <path d="M49.5 7c.8 5.2 2.3 6.7 7.5 7.5-5.2.8-6.7 2.3-7.5 7.5-.8-5.2-2.3-6.7-7.5-7.5 5.2-.8 6.7-2.3 7.5-7.5z"
            fill="#FFD36B" />
      <circle cx="55.6" cy="24.4" r="1.3" fill="#FFD36B" fillOpacity=".85" />
    </svg>
  );
}

export function LogoLockup({ size = 36, tone = 'light' }: { size?: number; tone?: 'light' | 'onDark' }) {
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
      <LogoMark size={size} />
      <div style={{ display: 'flex', flexDirection: 'column', lineHeight: 1.05 }}>
        <b style={{ fontSize: size * 0.53, letterSpacing: '.12em', fontWeight: 800,
                    color: tone === 'onDark' ? '#fff' : 'var(--brand-700)' }}>AASTAR</b>
        <span style={{ fontSize: Math.max(9, size * 0.26), letterSpacing: '.28em', fontWeight: 700, marginTop: 3,
                       color: tone === 'onDark' ? 'var(--accent-400)' : 'var(--accent-600)' }}>PRICE INTELLIGENCE</span>
      </div>
    </div>
  );
}
